"""web/src/data/examples.json: generated by scripts/precompute_examples.py, never hand-edited."""

import json

from src.agent import config

from server import contract

EXAMPLES = config.ROOT / "web" / "src" / "data" / "examples.json"
PAYLOAD_KEYS = {"status", "question", "summary", "columns", "rows", "display_rows", "chart", "assumptions", "sql",
                "truncated", "row_limit", "answered_ms", "attempts", "data_as_of", "source", "latency_ms",
                "retry_after_s"}


def load() -> dict:
    return json.loads(EXAMPLES.read_text())


def test_examples_match_the_current_prompt_and_payload_rules():
    """A prompt, model, effort or payload change must come with regenerated examples."""
    assert load()["cache_version"] == contract.cache_version()


def test_examples_are_complete_answers():
    data = load()
    assert len(data["examples"]) == 4
    for e in data["examples"]:
        assert set(e) == PAYLOAD_KEYS
        assert e["status"] == "answer" and e["source"] == "example" and e["rows"] and e["sql"]
        assert len(e["rows"]) == len(e["display_rows"])


def test_examples_record_where_they_came_from():
    data = load()
    assert data["model"] == config.MODEL and data["effort"] == config.EFFORT
    assert data["git_commit"] and data["computed_at"] and data["dataset"]["end_of_period"] == "2026-09-30"
